from pwn import *
import re

class ScreenBuffer:
    def __init__(self, rows=24, cols=80):
        self.rows = rows
        self.cols = cols
        self.buffer = [[' ' for _ in range(cols)] for _ in range(rows)]
        self.cur_row = 0
        self.cur_col = 0

    def write(self, char):
        if self.cur_row < self.rows and self.cur_col < self.cols:
            self.buffer[self.cur_row][self.cur_col] = char
            self.cur_col += 1

    def set_cursor(self, row, col):
        self.cur_row = min(row, self.rows - 1)
        self.cur_col = min(col, self.cols - 1)

    def get_line(self, row):
        return ''.join(self.buffer[row])

def parse_ansi(data):
    screen = ScreenBuffer()
    data = data.decode('latin1')

    # Split into parts
    parts = re.split(r'(\x1b\[[0-9;]*[A-Za-z])', data)

    password_chars = []
    found_password_line = False

    for part in parts:
        if part.startswith('\x1b['):
            # Parse ANSI escape sequence
            match = re.match(r'\x1b\[(\d+);(\d+)H', part)
            if match:
                row, col = map(int, match.groups())
                screen.set_cursor(row-1, col-1)
                if row == 8:  # Password line
                    password_chars.append((col, part[-1] if len(part) > 0 and part[-1].isalnum() else ''))
        else:
            # Regular text
            for char in part:
                if char not in '\r\n':
                    screen.write(char)
                elif char == '\n':
                    screen.cur_row += 1
                    screen.cur_col = 0

    # Sort password characters by column
    password_chars.sort(key=lambda x: x[0])
    password = ''.join(char[1] for char in password_chars if char[1])

    return password

def solve_challenge():
    conn = remote('misc.chal.csaw.io', 3535)
    print("Connected to server. Capturing initial output...")

    initial_output = conn.recv()
    password = parse_ansi(initial_output)

    print(f"\nExtracted password: {password}")

    if password:
        print(f"Sending password: {password}")
        conn.sendline(password.encode())

        try:
            response = conn.recv(timeout=2)
            print("\nServer Response:")
            print(response.decode('latin1'))
        except EOFError:
            print("Connection closed by server")

    conn.close()

if __name__ == "__main__":
    solve_challenge()

from pwn import *
import re

def collect_full_output(conn):
    buffer = b''
    while True:
        try:
            chunk = conn.recv(timeout=0.5)
            if not chunk:
                break
            buffer += chunk
        except EOFError:
            break
    return buffer

def parse_ansi_screen(data):
    # Convert to string while preserving all characters
    text = data.decode('latin1')

    # Create a 24x80 screen buffer
    screen = [[' ' for _ in range(80)] for _ in range(24)]
    current_row = 0
    current_col = 0

    # Process each character
    i = 0
    while i < len(text):
        if text[i] == '\x1b':
            # ANSI escape sequence
            if i + 1 < len(text) and text[i + 1] == '[':
                seq_end = text.find('H', i + 2)
                if seq_end != -1:
                    # Parse cursor position
                    params = text[i + 2:seq_end].split(';')
                    if len(params) == 2:
                        try:
                            current_row = max(0, int(params[0]) - 1)
                            current_col = max(0, int(params[1]) - 1)
                            i = seq_end + 1
                            continue
                        except ValueError:
                            pass
            i += 1
        else:
            # Regular character
            if text[i] not in '\r\n':
                if current_row < 24 and current_col < 80:
                    screen[current_row][current_col] = text[i]
                    current_col += 1
            elif text[i] == '\n':
                current_row += 1
                current_col = 0
            i += 1

    return screen

def find_password(screen):
    # Look for password in various rows
    for row_idx, row in enumerate(screen):
        line = ''.join(row).rstrip()
        print(f"Row {row_idx}: {line}")
        # Look for patterns that might be a password
        if any(c.isalnum() for c in line):
            password_match = re.search(r'[a-zA-Z0-9_]+', line)
            if password_match:
                candidate = password_match.group(0)
                if len(candidate) > 4:  # Assuming password is reasonably long
                    return candidate
    return None

def solve_challenge():
    conn = remote('misc.chal.csaw.io', 3535)
    print("Connected to server. Collecting output...")

    # Collect initial screen
    data = collect_full_output(conn)

    print("\nAnalyzing screen content...")
    screen = parse_ansi_screen(data)

    # Find password
    password = find_password(screen)

    if password:
        print(f"\nFound potential password: {password}")
        print("Sending password...")
        conn.sendline(password.encode())

        # Get response
        try:
            response = conn.recv(timeout=2)
            print("\nServer response:")
            print(response.decode('latin1'))

            # Check for flag format
            flag_match = re.search(r'flag{[^}]+}', response.decode('latin1'))
            if flag_match:
                print(f"\nFlag found: {flag_match.group(0)}")
        except EOFError:
            print("Connection closed by server")
    else:
        print("No password found in screen output")

    conn.close()

if __name__ == "__main__":
    solve_challenge()

from pwn import *

def extract_password(conn):
    screen = {}
    cursor_pos = [1, 1]
    in_escape = False
    escape_seq = ''

    while True:
        try:
            c = conn.recv(1)
            if not c:
                break

            if c == b'\x1b':
                in_escape = True
                escape_seq = c
                continue

            if in_escape:
                escape_seq += c
                if c.isalpha():
                    # Handle cursor position
                    if b'H' in escape_seq or b'f' in escape_seq:
                        pos = escape_seq.decode('ascii').strip('\x1b[]Hf').split(';')
                        if len(pos) == 2:
                            cursor_pos = [int(pos[0]), int(pos[1])]
                    in_escape = False
                    escape_seq = b''
                continue

            if 0x20 <= ord(c) <= 0x7E:
                key = f"{cursor_pos[0]},{cursor_pos[1]}"
                if key not in screen:
                    screen[key] = []
                screen[key].append(c.decode('ascii'))
                cursor_pos[1] += 1

        except EOFError:
            break

    # Extract line 8 characters
    line8 = []
    for key in sorted(screen.keys()):
        row, col = map(int, key.split(','))
        if row == 8:
            chars = screen[key]
            if len(chars) > 0:
                line8.append((col, chars[-1]))

    # Sort by column and extract characters
    password = ''.join(char for _, char in sorted(line8))
    return password

def solve_challenge():
    # Connect to server
    conn = remote('misc.chal.csaw.io', 3535)

    # Extract the password
    password = extract_password(conn)
    print(f"Extracted characters: {password}")

    # Send the potential password
    conn.sendline(b"Level Is Easy")

    # Get response
    try:
        response = conn.recvall(timeout=2)
        print("Server response:", response.decode('latin-1'))
    except:
        print("No response from server")

    conn.close()

if __name__ == "__main__":
    solve_challenge()

